import{_ as o,l as i,o as e,c as l,v as r,p as s,x as t,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"框架效应","description":"","frontmatter":{"title":"框架效应","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/framing-effects.md","filePath":"econ/framing-effects.md","lastUpdated":1789023840000}'),E={name:"econ/framing-effects.md"};function h(f,a,m,B,_,A){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="框架效应" tabindex="-1">框架效应 <a class="header-anchor" href="#框架效应" aria-label="Permalink to &quot;框架效应&quot;">​</a></h1><div class="epigraph"><p>同一统计，说成「救活 200 人」或「400 人死」，选择翻转——描述本身进入偏好。</p><footer>—— Tversky and Kahneman, The Framing of Decisions and the Psychology of Choice, Science, 1981</footer></div><p><a href="/econ/mental-accounting">上一课</a>把结果归入账户。本课缺口是陈述：客观菜单不变，措辞改变参考点与账户，选择翻转。不重写 \\(\\lambda\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>显示偏好假定菜单是客观集合。亚洲疾病问题：600 人受威胁，方案 A 确定救 200 人，方案 B 以 1/3 概率全救、2/3 概率无人获救；换成「死亡」框架后，确定方案变成厌恶对象。Tversky 与 Kahneman（1981）称之为框架效应。这不是新信息，概率相同。缺口是：前景理论的编辑阶段把描述编成不同的 \\((x,p)\\)，评价随后分叉。</p><p>家庭金融：缴费写成「匹配」或「税前扣除」、贷款写成「月供」或「总额」，默认与框架叠在一起。本课只钉描述依赖性。</p><p><span class="marginnote">不变性（invariance）是理性选择的隐含公理：同一选项的不同描述应给出同一选择。框架效应是对不变性的拒绝，比拒绝独立性更早：连菜单的同一性都没保住。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把一项政策写成收益框架与损失框架，保持概率与期望人数不变，比较选择。若翻转，则参考点被措辞移动：救活框架的参考点是「无人获救」，死亡框架的参考点是「无人死亡」。CPT 的四重模式预测：收益–确定被偏好，损失–确定被拒绝。</p>',9)),(e(),s(d,null,{default:t(()=>[p(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E7%90%86%E6%80%A7%3A%20%E6%8F%8F%E8%BF%B0%E4%B8%8D%E5%8F%98%E6%80%A7%22%5D%20--%3E%20FR%5B%22%E6%A1%86%E6%9E%B6%3A%20%E6%8E%AA%E8%BE%9E%E6%94%B9%E5%8F%82%E8%80%83%E7%82%B9%22%5D%0A%20%20FR%20--%3E%20ASIA%5B%22%E4%BA%9A%E6%B4%B2%E7%96%BE%E7%97%85%3A%20%E6%95%91%E6%B4%BB%20vs%20%E6%AD%BB%E4%BA%A1%22%5D%0A%20%20FR%20--%3E%20FIN%5B%22%E7%BC%B4%E8%B4%B9%E3%80%81%E6%9C%88%E4%BE%9B%E3%80%81%E8%BF%9D%E7%BA%A6%E7%9A%84%E9%99%88%E8%BF%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是编辑。决策者并不先把句子翻译成唯一的客观彩票，再调用 \\(v\\)。句子里的「救」「死」「损失」「收益」直接当编码。因此偏好不是备选集上的关系，而是<strong>被描述的备选集</strong>上的关系。这比<a href="/econ/preference-choice">偏好课</a>的完备传递更靠前：若描述变了，比较的根本不是同一个 \\(X\\)。</p><p>与助推的接口：选择架构包括默认，也包括框架。本课不把政策评价写成「应该用哪一种框架」，只标明预测会变。</p><p>不变性失败比独立性失败更底层：<a href="/econ/preference-choice">偏好</a>的 \\(X\\) 被假定为客观集合。若描述改变 \\(X\\) 的编码，完备传递可以在每个编码上成立，跨编码却不可比。亚洲疾病的概率与人数相同，变的只是「救」与「死」谁当参考点——收益框架走凹段，损失框架走凸段，确定方案的地位翻转。缴费与月供的陈述是同一逻辑的家庭金融版。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>并非所有措辞效应都是框架：有的陈述其实改变了信息（强调不同风险）。识别要求概率与结果可验证地相同。专业交易、经验反馈会减弱部分效应，与禀赋效应的经验文献平行。本课不估计效应量。</p><p>后课默认：禀赋效应是框架的一种——把「放弃」编成损失、「得到」编成收益。</p><p>不变性比独立性更底层：描述改变编码，完备传递可以在每个编码上成立、跨编码却不可比。</p><p>亚洲疾病的概率相同，变的是谁当参考点；缴费与月供是家庭金融版。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>框架效应拒绝描述不变性：同一统计，措辞翻转选择。</li><li>编辑把句子编进不同参考点，再调用已有的 \\(v\\)。</li><li>不重推斯勒茨基；需求理论的菜单被假定为客观，这里客观性先失败。</li><li>助推同时使用框架与默认。</li><li>识别要求结果与概率可验证地相同。</li><li>出处：Tversky and Kahneman, <em>Science</em> 1981。</li></ul>',11))])}const b=o(E,[["render",h]]);export{T as __pageData,b as default};
